@js:
try {
  var result = [];

  var m = source.getLoginInfoMap();
  var b = pickHealthyHost.call(this);
  if (!b) b = source.getKey();
  if (b.slice(-1) == '/') b = b.slice(0, -1);

  // 读取当前搜索类型
  function ysSetting(name, fallback) {
    var v = '';
    try {
      if (m) {
        if (m.get) v = m.get(name);
        if ((v === undefined || v === null || String(v).trim() === '') && m[name] !== undefined && m[name] !== null) v = m[name];
      }
    } catch (e0) {}
    if (v === undefined || v === null || String(v).trim() === '') {
      try { v = source.get('ysLoginUi_' + name); } catch (e1) {}
    }
    v = String(v === undefined || v === null ? '' : v).trim();
    return v || (fallback || '');
  }
  var st = ysSetting('搜索类型', '小说');
  if (st == '短剧') {
    var vt = ysSetting('短剧类型', '短剧');
    if (vt == '漫剧') st = '漫剧';
  }

  // 模式 → 旧分类文件索引映射；新版已覆盖的分类不再回退小说旧分类。
  var modeFileMap = {
    '综合': [],
    '小说': [2, 1],
    '出版': [],
    '听书': [4],
    '漫画': [5],
    '短剧': [6],
    '漫剧': [],
    '短篇': []
  };
  var fileIndexes = Object.prototype.hasOwnProperty.call(modeFileMap, st) ? modeFileMap[st] : [2, 1];

  function ysTitle(title) {
    title = String(title || '').replace(/^ +| +$/g, '');
    title = title.replace(/^▌ */, '');
    return title ? ('▌ ' + title) : '';
  }
  function ysSize(size) {
    size = Number(size || 1);
    if (size <= 0.26) return 0.33;
    if (size > 0.33 && size < 0.49) return 0.5;
    return size;
  }
  function push(title, url, size) {
    result.push({
      title: url ? title : ysTitle(title),
      url: url || '',
      style: { layout_flexGrow: 1, layout_flexBasisPercent: ysSize(size) }
    });
  }
  function pushButton(title, action, size) {
    result.push({
      title: title,
      type: 'button',
      action: action,
      style: { layout_flexGrow: 1, layout_flexBasisPercent: ysSize(size) }
    });
  }
  function pushText(title, action, defaultValue, size, viewName) {
    result.push({
      title: title,
      type: 'text',
      default: defaultValue || '',
      action: action,
      viewName: viewName || title,
      style: { layout_flexGrow: 1, layout_flexBasisPercent: ysSize(size) }
    });
  }

  // 从 category_landpage_url 提取 genreType 和 gender
  function extractParams(url) {
    var gt = '', gd = '';
    if (url) {
      var gtm = String(url).match(/genreType=(\d+)/);
      var gdm = String(url).match(/gender=(\d+)/);
      if (gtm) gt = gtm[1];
      if (gdm) gd = gdm[1];
    }
    return { genreType: gt, gender: gd };
  }

  function buildLandingUrl(cid, genreType, gender) {
    var extra = '';
    if (genreType) extra += '&genre_type=' + encodeURIComponent(genreType);
    if (gender) extra += '&gender=' + encodeURIComponent(gender);
    return "@js:var b=getServerHost.call(this);var p=parseInt(String(typeof page=='undefined'?1:page),10);if(!(p>0))p=1;result=b+'/api/landing?category_id=" + encodeURIComponent(String(cid)) + extra + "&offset='+encodeURIComponent(String((p-1)*10))";
  }

  // 搜索框
  ysExploreInit('综合', '推荐');
  var searchKey = ysExploreGet('ysSearch') || '';
  pushText('搜索关键词', "ysExploreSet((infoMap['搜索关键词'] || (infoMap.get && infoMap.get('搜索关键词'))), 'ysSearch')", searchKey, 0.68, "'搜索关键词：' + (ysExploreGet('ysSearch') || '')");
  pushButton('搜索', 'ysExploreSearch()', 0.28);

  push('当前模式：' + st, null, 1);
  var modeButtons = ['综合', '小说', '出版', '听书', '漫画', '短剧', '漫剧', '短篇'];
  for (var mbi = 0; mbi < modeButtons.length; mbi++) {
    var modeName = modeButtons[mbi];
    pushButton((modeName == st ? '✅ ' : '') + modeName, "ysSetSearchType('" + modeName + "')", 0.5);
  }
  push('搜索提示：关键词前加 +1/+2/+3/+4/+8/+11/+19 可临时切换综合/听书/小说/短篇/漫画/短剧/漫剧；10位以上 book_id 可直达详情。', null, 1);

  // 👤 个人中心（番茄登录后显示：昵称、书架、历史和书架分组）
  var ysSid = getSessionId.call(this);
  if (ysSid) {
    var ysUserName = '';
    try {
      var userRoot = JSON.parse(java.ajax(b + '/api/book_user?sessionid=' + encodeURIComponent(ysSid)) || '{}');
      var userData = (userRoot && userRoot.data) || {};
      ysUserName = String(userData.name || userData.user_name || '').trim();
    } catch (eUser) {}
    push('👤 ' + (ysUserName ? (ysUserName + ' 的个人中心') : '个人中心') + '', null, 1);
    push('📚 我的书架', b + '/api/book_shelf?sessionid=' + encodeURIComponent(ysSid), 0.5);
    push('🕘 阅读历史', b + '/api/read_history?sessionid=' + encodeURIComponent(ysSid) + '&offset={{(page-1)*20}}', 0.5);
    try {
      var shelfRoot = JSON.parse(java.ajax(b + '/api/book_shelf?meta=1&sessionid=' + encodeURIComponent(ysSid)) || '{}');
      var groups = (((shelfRoot || {}).data || {}).groups) || [];
      if (groups.length > 0) {
        push('📁 书架分组', null, 1);
        for (var gi = 0; gi < groups.length && gi < 20; gi++) {
          var groupName = String(groups[gi].name || '未分组');
          var groupCount = parseInt(groups[gi].count || 0, 10);
          push('📁 ' + groupName + (groupCount > 0 ? (' · ' + groupCount + '本') : ''), b + '/api/book_shelf?sessionid=' + encodeURIComponent(ysSid) + '&group=' + encodeURIComponent(groupName), 0.5);
        }
      }
    } catch (eShelf) {}
  }


  // 新版 bookmall cell/change 榜单 + recommend/homepage 推荐。
  var genreTabMap = {'综合':'2','小说':'2','出版':'3','短剧':'4','漫剧':'5','听书':'6','短篇':'7'};
  // 参考书源给出的全量榜单里有部分上游当前返回空；这里仅保留本地实测 count>0 的组合。
  var rankPresetMap = {
    '2': [['推荐榜','101'], ['完本榜','100'], ['追更榜','109'], ['黑马榜','102'], ['阅读榜','111']],
    '3': [['出版推荐','101'], ['典藏榜','196'], ['飙升榜','197']],
    '4': [['短剧推荐','101'], ['热播榜','502']],
    '5': [['漫剧推荐','550']],
    '6': [['听书榜','201']],
    '7': [['短篇榜','601']]
  };
  var homepageTabMap = {'小说':'25','听书':'5','漫剧':'24','短篇':'103'};
  function pushCellRank(title, genreTab, algoType, size) {
    push(title, b + '/api/bookmall/cell/change?genre_tab=' + encodeURIComponent(genreTab) + '&algo_type=' + encodeURIComponent(algoType) + '&offset={{(page-1)*10}}&limit=10', size || 0.33);
  }
  function pushHome(title, tabType, size) {
    push(title, b + '/api/recommend/homepage?tab_type=' + encodeURIComponent(tabType) + '&offset={{(page-1)*10}}&limit=10', size || 0.33);
  }

  if (st == '综合') {
    push('最新首页推荐（实测有数据）', null, 1);
    pushHome('综合推荐', '2', 0.33);
    pushHome('小说精选', '25', 0.33);
    pushHome('听书推荐', '5', 0.33);
    pushHome('漫剧推荐', '24', 0.33);
    pushHome('短篇推荐', '103', 0.33);
    push('新版发现榜单（参考源增强）', null, 1);
    var mixedRanks = [
      ['小说推荐','2','101'], ['小说完本','2','100'], ['小说追更','2','109'], ['小说黑马','2','102'], ['小说阅读','2','111'],
      ['出版推荐','3','101'], ['出版典藏','3','196'], ['出版飙升','3','197'],
      ['短剧推荐','4','101'], ['短剧热播','4','502'], ['漫剧推荐','5','550'], ['听书榜','6','201'], ['短篇榜','7','601']
    ];
    for (var mr = 0; mr < mixedRanks.length; mr++) pushCellRank(mixedRanks[mr][0], mixedRanks[mr][1], mixedRanks[mr][2], 0.33);
    // == 标签筛选：番茄分类 + 频道/完结状态/字数（/api/category & /api/category/books）==
    var curCh = ysExploreGet.call(this, 'cat_channel') || '男频';
    var curSt = ysExploreGet.call(this, 'cat_status') || '不限';
    var curWc = ysExploreGet.call(this, 'cat_word') || '不限';
    push('🏷 标签筛选 · ' + curCh + ' / ' + curSt + ' / ' + curWc + '', null, 1);
    result.push(ysExploreFilter.call(this, '频道', ['男频', '女频', '出版'], '男频', 'cat_channel', 0.33));
    result.push(ysExploreFilter.call(this, '状态', ['不限', '连载', '完结'], '不限', 'cat_status', 0.33));
    result.push(ysExploreFilter.call(this, '字数', ['不限', '百万内', '百万到三百万', '三百万+'], '不限', 'cat_word', 0.34));
    try {
      var chMap = { '男频': 'gender=1', '女频': 'gender=0', '出版': 'genre_type=160' };
      var stMap = { '不限': '9', '连载': '1', '完结': '0' };
      var wcMap = { '不限': '9', '百万内': '1', '百万到三百万': '3', '三百万+': '5' };
      var catJson = JSON.parse(java.ajax(b + '/api/category'));
      var catData = (catJson && catJson.data) || {};
      var arrKey = curCh == '女频' ? 'girl_category' : (curCh == '出版' ? 'publish_category' : 'boy_category');
      var cats = catData[arrKey] || [];
      var qs = (chMap[curCh] || 'gender=1') + '&creation_status=' + (stMap[curSt] || '9') + '&word_count=' + (wcMap[curWc] || '9');
      for (var ci = 0; ci < cats.length && ci < 28; ci++) {
        var cid = cats[ci].category_id || cats[ci].id;
        var cname = cats[ci].category_name || cats[ci].name || ('分类' + cid);
        push(cname, b + '/api/category/books?category_id=' + cid + '&' + qs + '&offset={{(page-1)*10}}&limit=10', 0.33);
      }
    } catch (eCat) {
      push('标签加载失败，请下拉刷新发现页', null, 1);
    }
  } else if (st == '漫画') {
    push('漫画发现', null, 1);
  } else {
    var genreTab = genreTabMap[st] || '2';
    if (homepageTabMap[st]) {
      push('首页推荐（实测有数据）', null, 1);
      pushHome(st + '推荐', homepageTabMap[st], 0.33);
    }
    if (st == '出版') {
      push('出版首页 tab 当前为空，已改用下方出版推荐/典藏/飙升榜。', null, 1);
    } else if (st == '短剧') {
      push('短剧首页 tab 当前为空，已改用下方短剧推荐/热播榜。', null, 1);
    }
    var cellRanks = rankPresetMap[genreTab] || [];
    if (cellRanks.length > 0) {
      push('新版发现榜单', null, 1);
      for (var cr = 0; cr < cellRanks.length; cr++) pushCellRank(cellRanks[cr][0], genreTab, cellRanks[cr][1], 0.33);
    }
  }


  // 从后端 /sy/{n}.json 加载分类
  for (var fi = 0; fi < fileIndexes.length; fi++) {
    var fileIdx = fileIndexes[fi];
    try {
      var raw = java.ajax(b + '/sy/' + fileIdx + '.json') || '{}';
      var root = JSON.parse(raw);
      var tabData = ((root || {}).data || {}).category_tab_data || {};
      var tabName = tabData.tab_name || '';
      var cells = tabData.cell_data || [];

      if (tabName) {
        push('' + tabName + '', null, 1);
      }

      for (var ci = 0; ci < cells.length; ci++) {
        var cell = cells[ci];
        var cellName = cell.cell_name || '';
        var atomData = cell.atom_data || [];

        if (cellName && atomData.length > 0) {
          // 第一个 atom 作为大分类标题
          var firstAtom = atomData[0].category_data || {};
          var firstCid = String(firstAtom.category_id || '');
          var firstParams = extractParams(firstAtom.category_landpage_url || '');
          if (firstCid) {
            push(cellName, buildLandingUrl(firstCid, firstParams.genreType, firstParams.gender), 1);
          } else {
            push(cellName, null, 1);
          }

          // 其余 atom 作为子分类按钮
          for (var ai = 1; ai < atomData.length; ai++) {
            var atom = atomData[ai].category_data || {};
            var cid = String(atom.category_id || '');
            var name = atom.name || '';
            var params = extractParams(atom.category_landpage_url || '');
            if (cid && name) {
              push(name, buildLandingUrl(cid, params.genreType, params.gender), 0.33);
            }
          }
        }
      }
    } catch (fileErr) {
      push(st + ' 分类加载失败', null, 1);
      try { java.log('洋柿子发现页分类加载失败: ' + fileErr); } catch(le) {}
    }
  }

  result = JSON.stringify(result);
} catch (e) {
  try { java.log('洋柿子发现页错误: ' + e); } catch (e1) {}
  result = JSON.stringify([{
    title: '洋柿子发现页加载失败',
    url: '',
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
  }]);
}

