// ===== 多服务器支持（书源地址为主 + 登录表单"后端地址"可追加镜像，合并成池）=====
function _ysCtx(self) {
  var c = self || {};
  return {
    java: (c.java != null ? c.java : (typeof java != 'undefined' ? java : null)),
    source: (c.source != null ? c.source : (typeof source != 'undefined' ? source : null)),
    cache: (c.cache != null ? c.cache : (typeof cache != 'undefined' ? cache : null)),
    cookie: (c.cookie != null ? c.cookie : (typeof cookie != 'undefined' ? cookie : null))
  };
}
function _ysNorm(u) {
  u = String(u == null ? '' : u).trim();
  if (u && u.slice(-1) === '/') u = u.slice(0, -1);
  return u;
}
function getHostList() {
  var src = _ysCtx(this).source;
  var list = [];
  try { var k = _ysNorm(src.getKey()); if (k) list.push(k); } catch (e) {}
  var raw = '';
  try { var m = src.getLoginInfoMap(); if (m && m.get('后端地址')) raw = String(m.get('后端地址')); } catch (e1) {}
  if (!raw) { try { raw = String(src.get('ysLoginUi_后端地址') || ''); } catch (e2) {} }
  if (raw) {
    var parts = raw.split(/[\s,，;；]+/);
    for (var i = 0; i < parts.length; i++) {
      var h = _ysNorm(parts[i]);
      if (h && /^https?:\/\//i.test(h) && list.indexOf(h) < 0) list.push(h);
    }
  }
  if (list.length === 0) { try { list.push(_ysNorm(src.getKey())); } catch (e3) {} }
  return list;
}
function _ysIdx() {
  try { var v = JSON.parse(_ysCtx(this).source.getVariable() || '{}'); var i = parseInt(v.hostIndex, 10); return (i >= 0) ? i : 0; } catch (e) { return 0; }
}
function _ysSetIdx(i) {
  try { var src = _ysCtx(this).source; var v = {}; try { v = JSON.parse(src.getVariable() || '{}') || {}; } catch (e0) {} v.hostIndex = i; src.setVariable(JSON.stringify(v)); } catch (e) {}
}
function getServerHost() {
  var list = getHostList.call(this);
  var i = _ysIdx.call(this);
  if (i < 0 || i >= list.length) i = 0;
  return list[i] || list[0] || '';
}
// 兼容旧调用：getBaseUrl 统一走多服务器
function getBaseUrl() { return getServerHost.call(this); }
// 番茄登录态：优先 fanqienovel.com 的 sessionid Cookie，回退手填的"番茄登录Token"
function getSessionId() {
  var ctx = _ysCtx(this), cookie = ctx.cookie, source = ctx.source;
  try { var ck = cookie ? String(cookie.getKey('fanqienovel.com', 'sessionid') || '') : ''; if (ck && ck !== 'null') return ck; } catch (e) {}
  try { var m = source.getLoginInfoMap(); var t = (m && m.get) ? m.get('番茄登录Token') : (m ? m['番茄登录Token'] : ''); return String(t || ''); } catch (e1) { return ''; }
}
// 探活 + 自动故障转移：返回一个健康 host（结果在内存缓存 3 分钟）
function pickHealthyHost() {
  var ctx = _ysCtx(this), java = ctx.java, cache = ctx.cache;
  var list = getHostList.call(this);
  if (list.length <= 1) return getServerHost.call(this);
  var ckey = 'ys_healthy_host';
  try {
    if (cache && cache.getFromMemory) {
      var rawc = cache.getFromMemory(ckey);
      if (rawc) {
        var p = String(rawc).split('|'); var host = p[0]; var ts = parseInt(p[1] || '0', 10);
        if (host && list.indexOf(host) >= 0 && (Date.now() - ts) < 180000) { _ysSetIdx.call(this, list.indexOf(host)); return host; }
      }
    }
  } catch (e) {}
  var start = _ysIdx.call(this);
  for (var n = 0; n < list.length; n++) {
    var idx = (start + n) % list.length; var h = list[idx];
    try {
      java.ajax(h + '/api/ping' + ',' + JSON.stringify({ method: 'GET', timeout: 4000 }));
      _ysSetIdx.call(this, idx);
      try { if (cache && cache.putMemory) cache.putMemory(ckey, h + '|' + Date.now()); } catch (e2) {}
      return h;
    } catch (e3) {}
  }
  return getServerHost.call(this);
}
// java.ajax 包装：失败自动轮转到下一服务器（用于子请求的故障转移）
function fetchJson(path) {
  var java = _ysCtx(this).java;
  var list = getHostList.call(this);
  var start = _ysIdx.call(this);
  for (var n = 0; n < list.length; n++) {
    var idx = (start + n) % list.length;
    try { var r = java.ajax(list[idx] + path); if (r) { if (idx !== start) _ysSetIdx.call(this, idx); return r; } } catch (e) {}
  }
  return '';
}
// 登录页：手动切换服务器
function ysSwitchServer() {
  var ctx = _ysCtx(this), java = ctx.java, cache = ctx.cache;
  var list = getHostList.call(this);
  if (list.length <= 1) { try { java.toast('只有 1 个服务器：\n' + (list[0] || '未配置')); } catch (e) {} return; }
  var i = (_ysIdx.call(this) + 1) % list.length;
  _ysSetIdx.call(this, i);
  try { if (cache && cache.putMemory) cache.putMemory('ys_healthy_host', ''); } catch (e1) {}
  try { java.toast('已切换到服务器 ' + (i + 1) + '/' + list.length + '：\n' + list[i]); } catch (e2) {}
}
// 登录页：检测各服务器延迟并自动选最快
function ysCheckServers() {
  var java = _ysCtx(this).java;
  var list = getHostList.call(this);
  var lines = ['📡 服务器延迟检测'];
  var best = -1, bestT = 1e9;
  for (var i = 0; i < list.length; i++) {
    var t0 = Date.now(), ok = false;
    try { java.ajax(list[i] + '/api/ping' + ',' + JSON.stringify({ method: 'GET', timeout: 5000 })); ok = true; } catch (e) {}
    var dt = Date.now() - t0;
    lines.push((i + 1) + '. ' + list[i] + '\n   ' + (ok ? ('✅ ' + dt + 'ms') : '❌ 不可用'));
    if (ok && dt < bestT) { bestT = dt; best = i; }
  }
  if (best >= 0) { _ysSetIdx.call(this, best); lines.push('\n✅ 已自动选用最快：' + (best + 1) + ' (' + bestT + 'ms)'); }
  else lines.push('\n⚠️ 无可用服务器，请检查地址/网络');
  try { java.longToast(lines.join('\n')); } catch (e1) {}
}
function svgToDataUrl(java, svg, clickConfig) {
  var url = "data:image/svg+xml;base64," + java.base64Encode(svg);
  if (clickConfig) url += "," + JSON.stringify(clickConfig);
  return url;
}
function createClickConfig(style, clickHandler) {
  return { style: style, type: "fq", click: clickHandler };
}

function ysExploreContext() {
  return {
    source: (this && this.source) || (typeof source != 'undefined' ? source : null),
    java: (this && this.java) || (typeof java != 'undefined' ? java : null)
  };
}
function ysExploreVariable() {
  var ctx = ysExploreContext.call(this);
  try {
    var raw = String(ctx.source.getVariable() || '').trim();
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}
function ysExploreSave(map) {
  var ctx = ysExploreContext.call(this);
  try {
    ctx.source.setVariable(JSON.stringify(map || {}, null, 2));
  } catch (e) {}
}
function ysExploreInit(defaultTab, defaultDim) {
  var map = ysExploreVariable.call(this);
  if (!map.ysTab) map.ysTab = defaultTab || '综合';
  if (!map.ysDim) map.ysDim = defaultDim || '全部';
  ysExploreSave.call(this, map);
}
function ysExploreGet(key) {
  var map = ysExploreVariable.call(this);
  return map[key];
}
function ysExploreShow(value, key) {
  var ctx = ysExploreContext.call(this);
  var data = ysExploreVariable.call(this);
  data[key] = String(value || '').trim();
  ysExploreSave.call(this, data);
  try {
    ctx.java.refreshExplore();
