indow.java\n    const { bid, cid, pid, itemVersion, baseUrl, paraText } = getUrlParams()\n    const isEndComment = String(pid) === '-1'\n    const isBookComment = String(pid) === '-2'\n    const commentOffsetMap = { 1: 0 }\n\n    function fixAvatar(url) {\n      let raw = String(url || '').trim()\n      if (!raw) return ''\n      const low = raw.toLowerCase()\n      if (window.location.origin.startsWith('https:') && low.startsWith('http:')) {\n        raw = 'https:' + raw.slice(5)\n      } else if (window.location.origin.startsWith('http:') && low.startsWith('https:')) {\n        raw = 'http:' + raw.slice(6)\n      }\n      return raw\n    }\n\n    function apiGetJson(path) {\n      const text = java.ajax(`${baseUrl}${path}`) || '{}'\n      return JSON.parse(String(text))\n    }\n\n    function normalizeOffset(value, fallback) {\n      function pick(v) {\n        if (v === undefined || v === null || v === '') return null\n        if (typeof v === 'number') return v\n        if (typeof v === 'string') {\n          const raw = v.trim()\n          if (!raw) return null\n          try {\n            return pick(JSON.parse(raw))\n          } catch (e) {\n            return raw\n          }\n        }\n        if (typeof v === 'object') {\n          if (v.offset !== undefined && v.offset !== null && v.offset !== '') return pick(v.offset)\n          if (v.next_offset !== undefined && v.next_offset !== null && v.next_offset !== '') return pick(v.next_offset)\n          if (v.cursor !== undefined && v.cursor !== null && v.cursor !== '') return pick(v.cursor)\n          if (v.next_cursor !== undefined && v.next_cursor !== null && v.next_cursor !== '') return pick(v.next_cursor)\n          return null\n        }\n        return String(v)\n      }\n      const picked = pick(value)\n      return picked === null || picked === '' ? fallback : picked\n    }\n\n    function fetchForumId() {\n      const root = apiGetJson(`/api/forum_id?book_id=${encodeURIComponent(bid)}&item_id=${encodeURIComponent(cid)}`)\n      const wrapped = ((root || {}).data || {})\n      const data = wrapped.data || wrapped || {}\n      const forumData = data.forum_data || data.forumData || {}\n      return String(forumData.forum_id || forumData.forumId || data.forum_id || data.forumId || '')\n    }\n\n    function normalizeCommentItem(item) {\n      const src = item && item.comment ? item.comment : (item && item.post_data ? item.post_data : (item || {}))\n      const common = src.common || item.common || {}\n      const userInfo = common.user_info || src.user_info || {}\n      const baseInfo = userInfo.base_info || userInfo || {}\n      const stat = src.stat || item.stat || {}\n      const text = src.text || src.pure_content || src.content || item.text || ''\n      return {\n        comment: {\n          ...src,\n          comment_id: src.comment_id || src.post_id || item.comment_id || item.post_id || item.id || '',\n          common: {\n            ...common,\n            create_timestamp: common.create_timestamp || src.create_timestamp || src.create_time || item.create_timestamp || item.create_time || src.time || 0,\n            content: common.content || { text: text },\n            user_info: {\n              ...userInfo,\n              base_info: {\n                ...baseInfo,\n                user_name: baseInfo.user_name || baseInfo.nickname || userInfo.user_name || '未知',\n                user_avatar: fixAvatar(baseInfo.user_avatar || baseInfo.avatar_url || baseInfo.avatar || userInfo.user_avatar || '')\n              }\n            }\n          },\n          stat: {\n            ...stat,\n            digg_count: stat.digg_count || src.digg_count || src.digg_cnt || item.digg_count || item.digg_cnt || 0,\n            reply_count: stat.reply_count || src.reply_count || src.reply_cnt || src.reply_outshow_count || src.reply_show_count || item.reply_count || item.reply_cnt || item.reply_outshow_count || item.reply_show_count || 0\n          }\n        }\n      }\n    }\n\n    function normalizeReplyItem(reply) {\n      const src = reply || {}\n      const common = src.Common || src.common || {}\n      const userInfo = common.user_info || src.user_info || {}\n      const baseInfo = userInfo.base_info || userInfo || {}\n      const replyTo = src.reply_to_user_info || src.reply_to_user || {}\n      const replyToBase = replyTo.base_info || replyTo || {}\n      const stat = src.stat || src.Stat || {}\n      const id = src.comment_id || src.reply_id || src.id || ''\n      const ctx = arguments.length > 1 && arguments[1] ? arguments[1] : {}\n      const groupId = src.reply_group_id || src.group_id || src.parent_id || src.root_id || ctx.group_id || ''\n      return {\n        ...src,\n        comment_id: id,\n        group_id: groupId,\n        reply_group_id: groupId,\n        __second_level: !!ctx.second,\n        Common: {\n          ...common,\n          create_timestamp: common.create_timestamp || src.create_timestamp || src.create_time || src.time || 0,\n          content: common.content || { text: src.text || src.pure_content || src.content || '' },\n          user_info: {\n            ...userInfo,\n            base_info: {\n              ...baseInfo,\n              user_name: baseInfo.user_name || baseInfo.nickname || userInfo.user_name || '未知',\n              user_avatar: fixAvatar(baseInfo.user_avatar || baseInfo.avatar_url || baseInfo.avatar || userInfo.user_avatar || '')\n            },\n            user_tag: userInfo.user_tag || {}\n          }\n        },\n        user_info: {\n          ...userInfo,\n          base_info: {\n            ...baseInfo,\n            user_name: baseInfo.user_name || baseInfo.nickname || userInfo.user_name || '未知',\n            user_avatar: fixAvatar(baseInfo.user_avatar || baseInfo.avatar_url || baseInfo.avatar || userInfo.user_avatar || '')\n          }\n        },\n        reply_to_user_info: {\n          ...replyTo,\n          base_info: {\n            ...replyToBase,\n            user_name: replyToBase.user_name || ''\n          }\n        },\n        stat: {\n          ...stat,\n          digg_count: stat.digg_count || src.digg_count || src.digg_cnt || 0,\n          reply_count: stat.reply_count || src.reply_count || src.reply_cnt || src.reply_outshow_count || 0\n        }\n      }\n    }\n\n    async function adaptParagraphList(url) {\n      const reqUrl = new URL(url, `${baseUrl}/`)\n      const page = parseInt(reqUrl.searchParams.get('page') || '1', 10)\n      const size = parseInt(reqUrl.searchParams.get('size') || '20', 10)\n      const offset = page === 1 ? 0 : normalizeOffset(commentOffsetMap[page] ?? commentOffsetMap.__next, (page - 1) * size)\n      let apiUrl\n      if (isBookComment) {\n        apiUrl = `/api/comments?book_id=${encodeURIComponent(bid)}&count=${encodeURIComponent(size)}&offset=${encodeURIComponent(String(offset))}`\n      } else if (isEndComment) {\n        const forumId = fetchForumId()\n        if (!forumId) throw new Error('获取 forum_id 失败')\n        apiUrl = `/api/end_comments?book_id=${encodeURIComponent(bid)}&item_id=${encodeURIComponent(cid)}&forum_id=${encodeURIComponent(forumId)}&count=${encodeURIComponent(size)}&offset=${encodeURIComponent(String(offset))}`\n      } else {\n        apiUrl = `/api/chapter_comments?book_id=${encodeURIComponent(bid)}&item_id=${encodeURIComponent(cid)}&item_version=${encodeURIComponent(itemVersion || '0')}&para_index=${encodeURIComponent(pid)}&count=${encodeURIComponent(size)}&offset=${encodeURIComponent(String(offset))}`\n      }\n      const root = apiGetJson(apiUrl)\n      const data = (root || {}).data || {}\n      const info = data.common_list_info || {}\n      const rawList = data.mix_data || data.data_list || data.comment_list || data.list || []\n      const nextOffset = normalizeOffset(data.next_offset ?? info.next_offset ?? data.offset ?? info.offset ?? data.next_cursor ?? info.next_cursor ?? data.cursor ?? info.cursor, offset + rawList.length)\n      const hasMore = data.has_more === false ? false : (info.has_more === false ? false : !!rawList.length)\n      if (nextOffset !== '' && nextOffset != null) {\n        commentOffsetMap[page + 1] = nextOffset\n        commentOffsetMap.__next = nextOffset\n      }\n      return {\n        code: 0,\n        data: {\n          common_list_info: {\n            total: Number(info.total || data.item_related_count || rawList.length || 0),\n            has_more: hasMore,\n            offset: nextOffset\n          },\n          data_list: rawList.map(normalizeCommentItem),\n          mix_data: rawList,\n          item_related_count: Number(info.total || data.item_related_count || rawList.length || 0),\n          has_more: hasMore,\n          extra: {\n            para_content: isBookComment\n              ? ((data.extra && data.extra.book_info && data.extra.book_info.book_name ? '《' + String(data.extra.book_info.book_name).trim() + '》书籍评论' : '') || '书籍评论')\n              : (isEndComment\n                ? ((data.extra && data.extra.para_content ? String(data.extra.para_content).trim() : '') || '章评')\n                : ((data.extra && data.extra.para_content ? String(data.extra.para_content).trim() : '') || paraText)),\n            book_info: data.extra && data.extra.book_info ? data.extra.book_info : {}\n          }\n        }\n      }\n    }\n\n    async function adaptReplyList(url) {\n      const reqUrl = new URL(url, baseUrl + '/')\n      const rid = String(reqUrl.searchParams.get('rid') || '')\n      const groupId = String(reqUrl.searchParams.get('group_id') || '')\n      const parentKind = String(reqUrl.searchParams.get('kind') || '')\n      const second = String(reqUrl.searchParams.get('second') || '') == '1'\n      const page = parseInt(reqUrl.searchParams.get('page') || '1', 10)\n      const size = parseInt(reqUrl.searchParams.get('size') || '5', 10)\n      const offset = Math.max(0, (page - 1) * size)\n      const requestCount = isBookComment ? Math.max(size, page * size) : size\n      let root\n      if (isBookComment) {\n        root = second\n          ? apiGetJson('/api/comments_reply_reply?book_id=' + encodeURIComponent(bid) + '&reply_id=' + encodeURIComponent(rid) + '&count=' + encodeURIComponent(requestCount))\n          : apiGetJson('/api/comments_reply?book_id=' + encodeURIComponent(bid) + '&comment_id=' + encodeURIComponent(rid) + '&count=' + encodeURIComponent(requestCount))\n      } else if (isEndComment) {\n        if (parentKind == 'post' && !second) {\n          root = apiGetJson('/api/end_comments_reply?book_id=' + encodeURIComponent(bid) + '&post_id=' + encodeURIComponent(rid) + '&offset=' + encodeURIComponent(String(offset)) + '&count=' + encodeURIComponent(size))\n        } else {\n          root = apiGetJson('/api/end_comments_reply_reply?book_id=' + encodeURIComponent(bid) + '&group_id=' + encodeURIComponent(groupId || rid) + '&comment_id=' + encodeURIComponent(rid) + '&offset=' + encodeURIComponent(String(offset)) + '&count=' + encodeURIComponent(size))\n        }\n      } else {\n        root = apiGetJson('/api/comment_replies?book_id=' + encodeURIComponent(bid) + '&item_id=' + encodeURIComponent(cid) + '&comment_id=' + encodeURIComponent(rid) + '&count=' + encodeURIComponent(size) + '&offset=' + encodeURIComponent(String(offset)))\n      }\n      const wrapped = ((root || {}).data || {})\n      const data = wrapped.data || wrapped || {}\n      const info = data.comment_list_info || data.common_list_info || {}\n      const commentObj = data.comment && !Array.isArray(data.comment) ? data.comment : {}\n      const rawList = Array.isArray(data.comment) ? data.comment : (data.reply_list || data.data_list || data.replies || data.comments || commentObj.reply_list || commentObj.data_list || commentObj.replies || [])\n      const pageList = isBookComment ? rawList.slice(offset, offset + size) : rawList\n      const replyGroupId = isEndComment ? (groupId || (parentKind == 'post' ? rid : '')) : groupId\n      const nextOffset = normalizeOffset(data.next_offset ?? info.next_offset ?? data.offset ?? info.offset ?? data.next_cursor ?? info.next_cursor ?? data.cursor ?? info.cursor, offset + pageList.length)\n      const total = Number(data.count || info.total || rawList.length || 0)\n      const hasMore = isBookComment\n        ? pageList.length > 0 && rawList.length >= requestCount\n        : (data.has_more === false ? false : (info.has_more === false ? false : !!rawList.length))\n      return {\n        code: 0,\n        data: {\n          reply_list: pageList.map(item => normalizeReplyItem(item, { group_id: replyGroupId, second: second })),\n          referer_comment: data.comment && !Array.isArray(data.comment) ? normalizeReplyItem(data.comment, { group_id: replyGroupId, second: second }) : null,\n          comment_list_info: {\n            total: total,\n            offset: nextOffset,\n            has_more: hasMore\n          }\n        }\n      }\n    }\n\n    async function fetchWithToken(url, options = {}) {\n      if (url.startsWith('./paragraph_list?') || url.startsWith('./chapter_list?') || url.startsWith('./novel_list?')) {\n        return { json: async () => adaptParagraphList(url) }\n      }\n      if (url.startsWith('./reply?')) {\n        return { json: async () => adaptReplyList(url) }\n      }\n      const absoluteUrl = /^https?:\\/\\//.test(url) ? url : `${baseUrl}/${String(url).replace(/^\\.\\//, '')}`\n      return fetch(absoluteUrl, options)\n    }\n\n    /** @type {'paragraph' | 'chapter' | 'novel'} 评论类型：段评 or 章评 or 书评 */\n    const type = isBookComment ? 'novel' : (isEndComment ? 'chapter' : 'paragraph')\n    const typeZH = type === \"paragraph\" ? '段评' : type === \"chapter\" ? '章评' : '书评'\n    window.document.title = `${typeZH}页`\n\n    let commentPage = 1 // 评论列表当前页码\n    let commentTotalCount = 0 // 评论总数\n    const commentSize = 20 // 评论列表每页条数\n    let isCommentEnd = false // 评论是否加载完毕\n    let isLoading = false // 防止重复加载评论\n    let renderedCommentCount = 0\n    const commentPageCache = {}\n    const commentPrefetching = {}\n    let fullscreenScale = 1   // 记录全屏图片当前缩放比例\n    const scaleStep = 0.1 // 缩放步长（每次滚轮滚动的缩放幅度）\n    const minScale = 0.2 // 缩放范围限制\n    const maxScale = 5\n    const imageCache = new Map() // 图片转码缓存\n\n    const errorAlert = document.getElementById('errorAlert')\n    const loading = document.getElementById('loading')\n    const commentCountElement = document.getElementById('commentCount')\n    const commentList = document.getElementById('commentList')\n    const fullscreenOverlay = document.getElementById('fullscreenOverlay')\n    const fullscreenImg = document.getElementById('fullscreenImg')\n    const detailView = document.createElement('div')\n    detailView.className = 'space-y-2 hidden'\n    commentList.parentNode.insertBefore(detailView, commentList.nextSibling)\n    const backFloat = document.createElement('button')\n    backFloat.textContent = '返回评论'\n    backFloat.className = 'hidden'\n    backFloat.style.cssText = 'position:fixed;right:16px;bottom:24px;z-index:9999;border:1px solid rgba(31,28,24,.10);border-radius:8px;background:rgba(255,250,242,.94);color:#6b6258;padding:8px 12px;font-size:13px;box-shadow:0 8px 24px rgba(69,49,26,.12);backdrop-filter:blur(12px);'\n    document.body.appendChild(backFloat)\n    let mainTitleText = ''\n    let detailReplyState = null\n    const detailReplyStack = []\n    const likeSvg = '<svg class=\"w-4 h-4 mr-1\" fill=\"none\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><g clip-rule=\"evenodd\" fill=\"currentColor\" fill-rule=\"evenodd\"><path d=\"m11.6934 5.05855c.6491-.9737 1.7419-1.55855 2.9122-1.55855h.2139c.9269 0 1.632.8323 1.4796 1.7466l-.6118 3.6712c-.0508.30477.1842.5822.4932.5822h2.3799c1.5776 0 2.7608 1.4433 2.4514 2.9903l-1.2 6c-.2337 1.1686-1.2597 2.0097-2.4514 2.0097h-11.3604c-1.38071 0-2.5-1.1193-2.5-2.5v-8c0-.27614.22386-.5.5-.5h3.92963c.50153 0 .96988-.25065 1.24808-.66795zm2.9122-.55855c-.8359 0-1.6165.41775-2.0802 1.11325l-2.5156 3.7735c-.46