sList.add('hidden')\n      commentCountElement.classList.add('hidden')\n      commentList.classList.add('hidden')\n      errorAlert.classList.remove('hidden')\n      refreshError(message, 3)\n    }\n\n    function refreshError(msg, leftSeconds) {\n      if (leftSeconds <= 0) {\n        errorAlert.textContent = ''\n        errorAlert.classList.add('hidden')\n        commentCountElement.classList.remove('hidden')\n        commentList.classList.remove('hidden')\n        window.scrollTo(scrollX, scrollY)\n        isLoading = false // 恢复加载\n        return\n      }\n      errorAlert.textContent = `${msg}\\t\\t${leftSeconds}s后自动返回……`\n      setTimeout(() => refreshError(msg, leftSeconds - 1), 1000)\n    }\n\n    // 点击图片/头像触发全屏\n    function initFullscreenImage() {\n      document.addEventListener('click', (e) => {\n        const target = e.target\n        if (target.classList.contains('avatar') || target.classList.contains('comment-img')) {\n          // 如果存在HEIC转码缓存\n          if (imageCache.has(target.src)) {\n            fullscreenImg.src = imageCache.get(target.src)\n          } else {\n            fullscreenImg.src = target.src\n          }\n          fullscreenImg.alt = target.alt\n          fullscreenScale = 1\n          fullscreenImg.style.transform = `scale(${fullscreenScale})`\n          fullscreenOverlay.classList.remove('hidden')\n          document.body.style.overflow = 'hidden'\n        }\n      })\n\n      fullscreenOverlay.addEventListener('click', closeFullscreen)\n      document.addEventListener('keydown', (e) => {\n        if (e.key === 'Escape' && !fullscreenOverlay.classList.contains('hidden')) {\n          closeFullscreen()\n        }\n      })\n\n      fullscreenImg.addEventListener('wheel', (e) => {\n        e.stopPropagation() // 阻止事件冒泡，避免影响页面其他元素\n        e.preventDefault() // 阻止页面滚动\n        // 根据滚轮方向计算新缩放比例\n        if (e.deltaY < 0) {\n          // 向上滚动：放大\n          fullscreenScale = Math.min(fullscreenScale + scaleStep, maxScale)\n        } else {\n          // 向下滚动：缩小\n          fullscreenScale = Math.max(fullscreenScale - scaleStep, minScale)\n        }\n        // 应用缩放\n        fullscreenImg.style.transform = `scale(${fullscreenScale})`\n      })\n\n      // 封装关闭全屏的统一逻辑（方便复用和重置）\n      function closeFullscreen() {\n        fullscreenOverlay.classList.add('hidden')\n        document.body.style.overflow = ''\n        // 退出时重置图片缩放比例（下次打开是原尺寸）\n        fullscreenScale = 1\n        fullscreenImg.style.transform = `scale(${fullscreenScale})`\n      }\n    }\n\n    // 渲染用户头衔\n    function renderTitles(userTitleInfoList, isAuthor) {\n      const titlesContainer = document.createDocumentFragment()\n      if (!userTitleInfoList || !Array.isArray(userTitleInfoList)) return titlesContainer\n      userTitleInfoList.forEach(titleInfo => {\n        try {\n          if (!titleInfo?.label) return\n          if (titleInfo.is_author_title && !isAuthor) return\n          const label = JSON.parse(titleInfo.label)\n          if (!label.title_text) return\n          const titleSpan = document.createElement('span')\n          titleSpan.className = 'inline-block px-1.5 py-0.5 rounded text-xs mx-0.5'\n          // 处理文本颜色\n          titleSpan.style.color = label.title_default_color || ''\n          // 处理背景\n          let bgValue = ''\n          if (label.bg_default_color) {\n            if (typeof label.bg_default_color === 'string') {\n              // 情况1：渐变格式（字符串JSON）\n              if (label.bg_default_color.startsWith('{') && label.bg_default_color.endsWith('}')) {\n                try {\n                  const bgObj = JSON.parse(label.bg_default_color)\n                  if (bgObj.start && bgObj.end) {\n                    // 修复透明度格式可能的解析问题（确保浏览器识别 #RRGGBBAA 格式）\n                    const start = normalizeColorFormat(bgObj.start)\n                    const end = normalizeColorFormat(bgObj.end)\n                    bgValue = `linear-gradient(90deg, ${start}, ${end})`\n                  } else {\n                    bgValue = normalizeColorFormat(label.bg_default_color)\n                  }\n                } catch (e) {\n                  bgValue = normalizeColorFormat(label.bg_default_color)\n                }\n              }\n              // 情况2：直接纯色字符串\n              else {\n                bgValue = normalizeColorFormat(label.bg_default_color)\n              }\n            } else {\n              bgValue = label.bg_default_color\n            }\n          }\n          if (bgValue) {\n            const finalBgValue = typeof bgValue === 'string' ? applyAlphaToBackground(bgValue) : bgValue\n            // 设置背景色和背景透明度\n            titleSpan.style.background = finalBgValue\n            // 兼容部分浏览器，同时设置 backgroundImage（渐变时生效）\n            if (typeof finalBgValue === 'string' && finalBgValue.startsWith('linear-gradient')) {\n              titleSpan.style.backgroundImage = finalBgValue\n            }\n          }\n          titleSpan.textContent = label.title_text\n          titlesContainer.appendChild(titleSpan)\n        } catch (e) {\n          console.error('头衔渲染失败:', userTitleInfoList, e)\n          // 解析失败不显示\n        }\n      })\n      return titlesContainer\n    }\n\n    /**\n     * 标准化颜色格式（处理可能的透明度格式问题）\n     * 确保 #RRGGBBAA 或 #RGBA 格式被浏览器正确识别\n     */\n    function normalizeColorFormat(color) {\n      if (!color) return color\n      // 移除可能的空格\n      const cleanColor = color.trim()\n      // 处理类似 \"{\\\"start\\\":\\\"#1AFA6725\\\"}\" 解析后可能残留的引号（如果有）\n      const unquotedColor = cleanColor.replace(/^[\"']|[\"']$/g, '')\n      // 验证是否为十六进制格式，补充可能缺失的 #（如果有）\n      if (/^[0-9A-Fa-f]{6,8}$/.test(unquotedColor)) {\n        return `#${unquotedColor}`\n      }\n      return unquotedColor\n    }\n\n    /**\n     * 给背景色添加透明度（支持 #RRGGBB / #RRGGBBAA 和 linear-gradient 内的 hex）\n     */\n    function applyAlphaToBackground(bg, alpha = 0.1) {\n      if (!bg || typeof bg !== 'string') return bg\n      const safeAlpha = Math.min(Math.max(alpha, 0), 1)\n      const alphaHex = Math.round(safeAlpha * 255).toString(16).padStart(2, '0')\n\n      function withAlpha(hexColor) {\n        const normalized = normalizeColorFormat(hexColor)\n        if (typeof normalized !== 'string') return hexColor\n        const match = normalized.match(/^#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$/)\n        if (!match) return normalized\n        const hexBody = match[1]\n        if (hexBody.length === 8) {\n          return `#${hexBody.slice(0, 6)}${alphaHex}`\n        }\n        return `#${hexBody}${alphaHex}`\n      }\n\n      if (bg.startsWith('linear-gradient')) {\n        return bg.replace(/#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})\\b/g, (color) => withAlpha(color))\n      }\n\n      return withAlpha(bg)\n    }\n\n    // 渲染图片\n    function renderImageContent(imageData) {\n      const container = document.createDocumentFragment()\n      if (!imageData || !Array.isArray(imageData) || !imageData.length) return container\n      const firstImage = imageData[0]\n      const imageUrl = firstImage.expand_web_url || firstImage.web_uri || firstImage.web_url || ''\n      const isAIGC = !!firstImage.aigc_image_id\n      if (!imageUrl) return container\n      // 创建图片容器\n      const imgContainer = document.createElement('div')\n      imgContainer.className = 'relative mt-1 block w-fit'\n      // 创建加载占位符\n      const placeholder = document.createElement('div')\n      placeholder.className = 'image-loading rounded-md max-w-[40vw] max-w-[160px] w-[160px] h-[160px]'\n      imgContainer.appendChild(placeholder)\n      // 创建图片元素\n      const img = document.createElement('img')\n      img.className = 'comment-img rounded-md max-w-[40vw] max-w-[160px] w-auto h-auto cursor-pointer hover:scale-[1.02] transition-transform opacity-0 transition-opacity duration-300 top-0 left-0'\n      img.alt = '评论图片'\n      // 图片加载完成处理\n      img.onload = function () {\n        // 隐藏占位符，显示图片并添加淡入效果\n        placeholder.classList.add('hidden')\n        img.classList.remove('opacity-0')\n      }\n      // 图片加载失败处理\n      img.onerror = function () {\n        placeholder.classList.remove('image-loading')\n        placeholder.classList.add('bg-gray-100', 'flex', 'items-center', 'justify-center', 'text-gray-400')\n        placeholder.innerHTML = '<svg class=\"w-8 h-8\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z\"></path></svg>'\n      }\n      // 处理图片URL\n      handleImageUrl(imageUrl).then(url => img.src = url)\n      imgContainer.appendChild(img)\n      // 添加AI生成水印\n      if (isAIGC) {\n        const watermark = document.createElement('span')\n        watermark.className = 'absolute top-2 right-2 bg-black/70 text-white text-xs px-1 py-0.5 rounded z-10'\n        watermark.textContent = 'AI生成'\n        imgContainer.appendChild(watermark)\n      }\n      container.appendChild(imgContainer)\n      return container\n    }\n\n    // 渲染视频\n    function renderVideoContent(videoInfo) {\n      const container = document.createDocumentFragment()\n      if (!videoInfo || !videoInfo.video_model) return container\n      try {\n        const videoData = JSON.parse(videoInfo.video_model)\n        if (!videoData || typeof videoData !== 'object') return container\n\n        const posterUrl = videoInfo.first_frame_poster || videoData.poster_url || ''\n        const video1 = videoData.video_list?.video_1\n        if (!video1) return container\n        if (!video1.main_url && !video1.backup_url_1) return container\n        // 视频转发\n        const finalVideoUrl = `./video?url=${encodeURIComponent(video1.main_url || '')}&url=${encodeURIComponent(video1.backup_url_1 || '')}&token=${encodeURIComponent(token)}`\n\n        // 创建视频容器\n        const videoContainer = document.createElement('div')\n        videoContainer.className = 'mt-1 block w-fit relative'\n        // 创建视频初始显示容器（poster图 + 水印 + 播放按钮）\n        const playInitiator = document.createElement('div')\n        playInitiator.className = 'cursor-pointer relative max-w-[40vw] max-w-[160px] rounded-md overflow-hidden'\n        playInitiator.title = '点击播放视频'\n        // 视频封面占位符\n        const posterPlaceholder = document.createElement('div')\n        posterPlaceholder.className = 'image-loading rounded-md max-w-full w-full h-[160px]'\n        playInitiator.appendChild(posterPlaceholder)\n        // 海报图\n        const posterImg = document.createElement('img')\n        posterImg.className = 'w-auto h-auto max-w-full rounded-md opacity-0 transition-opacity duration-300 top-0 left-0'\n        posterImg.alt = '视频封面'\n        // 海报图加载完成处理\n        posterImg.onload = function () {\n          posterPlaceholder.classList.add('hidden')\n          posterImg.classList.remove('opacity-0')\n        }\n        // 海报图加载失败处理\n        posterImg.onerror = function () {\n          posterPlaceholder.classList.remove('image-loading')\n          posterPlaceholder.classList.add('bg-gray-100', 'flex', 'items-center', 'justify-center', 'text-gray-400')\n          posterPlaceholder.innerHTML = '<svg class=\"w-8 h-8\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z\"></path></svg>'\n        }\n        if (posterUrl) {\n          handleImageUrl(posterUrl).then(processedUrl => posterImg.src = processedUrl)\n        }\n        playInitiator.appendChild(posterImg)\n        // AI视频水印\n        const aiWatermark = document.createElement('div')\n        aiWatermark.className = 'absolute top-2 right-2 bg-black/70 text-white text-xs px-1 py-0.5 rounded z-10'\n        aiWatermark.textContent = 'AI视频'\n        playInitiator.appendChild(aiWatermark)\n        // 播放按钮\n        const playBtn = document.createElement('div')\n        playBtn.className = 'absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-12 h-12 bg-[#dc2626]/70 rounded-full flex items-center justify-center text-white text-2xl z-10 hover:bg-[#dc2626]/90 transition-colors'\n        playBtn.innerHTML = '▷'\n        playInitiator.appendChild(playBtn)\n\n        // 创建视频元素\n        const video = document.createElement('video')\n        video.className = 'rounded-md max-w-[50vw] max-w-[320px] w-auto h-auto hidden'\n        video.controls = true\n        video.preload = 'metadata'\n        if (posterUrl) {\n          handleImageUrl(posterUrl).then(processedUrl => video.poster = processedUrl)\n        }\n\n        // 点击初始容器触发播放\n        playInitiator.addEventListener('click', () => {\n          // 隐藏初始容器，显示视频\n          playInitiator.classList.add('hidden')\n          video.classList.remove('hidden')\n          video.src = finalVideoUrl\n          video.load()\n          video.play().catch(err => {\n            console.warn('自动播放被浏览器限制，需用户手动点击播放:', err)\n          })\n        })\n\n        // 视频加载错误处理\n        video.addEventListener('error', () => {\n          console.error('视频加载失败:', video.error)\n          const errorEl = document.createElement('div')\n          errorEl.className = 'text-red-500 text-sm mt-1'\n          errorEl.textContent = '视频加载失败：' + (video.error?.message || '未知错误')\n          videoContainer.appendChild(errorEl)\n        })\n\n        // 组装视频容器\n        videoContainer.appendChild(playInitiator)\n        videoContainer.appendChild(video)\n        container.appendChild(videoContainer)\n      } catch (e) {\n        console.error('视频评论处理失败:', videoInfo, e)\n      }\n      return container\n    }\n\n    // 常见HEIC/HEIF对应的MIME类型\n    const HEIC_MIME_TYPES = new Set([\n      'image/heic',\n      'image/heif',\n      'image/heic-sequence',\n      'image/heif-sequence',\n      'image/x-heic',\n      'image/x-heif'\n    ])\n\n    async function fetchImageBlob(url) {\n      try {\n        // 避免混合内容问题\n        if (window.location.origin.startsWith('https:') && url.startsWith('http:')) {\n          url = url.replace('http:', 'https:')\n        } else if (window.location.origin.startsWith('http:') && url.startsWith('https:')) {\n          url = url.replace('https:', 'http:')\n        }\n        const response = await fetch(url)\n        if (!response.ok) throw new Error(`HTTP 错误: ${response.status}`)\n        const blob = await response.blob()\n        // 基于Blob的MIME类型和URL后缀判断是否为HEIC\n        const isHeic = HEIC_MIME_TYPES.has(blob.type) || /[.](heic|heif)(?:$|[?#])/i.test(url)\n        return { blob, isHeic }\n      } catch (error) {\n        console.error('获取图片Blob失败:', url, error)\n        throw error\n      }\n    }\n\n    // 统一处理图像：兼容HEIC转码\n    async function handleImageUrl(originalUrl) {\n      const fixedUrl = fixAvatar(originalUrl)\n      if (!fixedUrl) return ''\n      if (imageCache.has(fixedUrl)) return imageCache.get(fixedUrl)\n      try {\n        // 获取Blob并判断是否为HEIC\n        const { blob, isHeic } = await fetchImageBlob(fixedUrl)\n        let usableUrl\n        if (isHeic) {\n          // HEIC格式：转码为PNG\n          const pngBlob = await heic2any({\n            blob: blob,\n            toType: 'image/png',\n            quality: 1 // 无损转码\n          })\n          usableUrl = URL.createObjectURL(pngBlob)\n        } else {\n          // 非HEIC格式：直接生成Blob URL\n          usableUrl = URL.createObjectURL(blob)\n        }\n        // 存入缓存\n        imageCache.set(fixedUrl, usableUrl)\n        return usableUrl\n      } catch (error) {\n        return fixedUrl // 失败则返回原始URL\n      }\n    }\n\n    // 渲染单条评论\n    function renderComment(comment) {\n      const commentItem = document.createElement('div')\n      commentItem.className = 'comment-card flex gap-3 py-3 px-3 mb-3'\n      if (!comment || typeof comment !== 'object') return commentItem\n      const rid = comment.comment_id || comment.post_id || comment.id || ''\n      commentItem.setAttribute('data-review-id', rid)\n\n      // 头像容器\n      const avatarContainer = document.createElement('div')\n      avatarContainer.className = 'relative w-10 h-10 flex shrink-0 items-center justify-center'\n      // 头像框\n      // if (comment.frameUrl) {\n      //   const frameImg = document.createElement('img')\n      //   frameImg.className = 'absolute inset-0 w-full h-full object-contain'\n      //   frameImg.src = comment.frameUrl\n      //   frameImg.alt = '头像框'\n      //   frameImg.onerror = () => frameImg.classList.add('hidden') // 加载失败时隐藏\n      //   avatarContainer.appendChild(frameImg)\n      // }\n      // 头像占位符\n      const avatarPlaceholder = document.createElement('div')\n      avatarPlaceholder.className = 'image-loading absolute w-9 h-9 rounded-full'\n      avatarContainer.appendChild(avatarPlaceholder)\n      // 头像\n      const avatar = document.createElement('img')\n      avatar.className = 'avatar w-9 h-9 rounded-full object-cover cursor-pointer relative z-10 opacity-0 transition-opacity duration-300'\n      // 头像加载完成处理\n      avatar.onload = function () {\n        avatarPlaceholder.classList.add('hidden')\n        avatar.classList.remove('opacity-0')\n      }\n      // 头像加载失败处理\n      avatar.onerror = function () {\n        avatarPlaceholder.classList.remove('image-loading')\n        avatarPlaceholder.classList.add('bg-gray-100', 'flex', 'items-center', 'justify-center', 'text-gray-400')\n        avatarPlaceholder.innerHTML = '<svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z\"></path></svg>'\n      }\n      // 处理头像URL（HEIC转码）\n      const userInfoData = comment.common?.user_info?.base_info || comment?.user_info || {}\n      handleImageUrl(userInfoData.user_avatar || '').then(url => avatar.src = url)\n      avatar.alt = userInfoData.user_name || '用户'\n      avatarContainer.appendChild(avatar)\n      commentItem.appendChild(avatarContainer)\n\n      const commentContent = document.createElement('div')\n      commentContent.className = 'flex-1 min-w-0'\n      commentItem.appendChild(commentContent)\n\n      const commentHeader = document.createElement('div')\n      commentHeader.className = 'flex justify-between items-start gap-2'\n\n      const userInfo = document.createElement('div')\n      userInfo.className = 'flex items-center min-w-0 flex-wrap gap-y-1'\n\n      const nickname = document.createElement('span')\n      nickname.className = 'font-semibold text-stone-700 text-xs-sm mr-2 max-w-[58vw] truncate'\n      nickname.textContent = userInfoData.user_name || '未知'\n      userInfo.appendChild(nickname)\n\n      // 头衔渲染\n      const userTitleInfoList = comment.common?.user_info?.user_tag?.user_title_info ||\n        comment.user_info?.user_title_infos ||\n        []\n      userInfo.appendChild(renderTitles(userTitleInfoList, comment.user_action?.author))\n\n      // 楼数\n      // const floor = document.createElement('span')\n      // floor.className = 'text-gray-400 text-sm'\n      // floor.textContent = comment.floor ? `${comment.floor}楼` : ''\n\n      commentHeader.appendChild(userInfo)\n      // commentHeader.appendChild(floor)\n      commentContent.appendChild(commentHeader)\n\n      // 评论内容（文字+图片+音频+视频+评价）\n      const commentBody = document.createElement('div')\n      commentBody.className = 'mt-1.5'\n      const content = document.createElement('p')\n      content.className = 'comment-text'\n      content.innerHTML = formatEmoji(\n        comment.common?.content?.text ||\n        comment.text ||\n        comment.pure_content ||\n        ''\n      ).replace(/\\n/g, '<br>')\n      commentBody.appendChild(content)\n\n      // 图片\n      const imageData = comment.common?.content?.image_data_list?.image_data || comment.image_data || []\n      const imageContent = renderImageContent(imageData)\n      if (imageContent.children.length > 0) {\n        commentBody.appendChild(imageContent)\n      }\n      // 视频\n      const videoInfo = comment.expand?.video_info || comment.video_info\n      const videoContent = renderVideoContent(videoInfo)\n      if (videoContent.children.length > 0) {\n        commentBody.appendChild(videoContent)\n      }\n      // 处理书评的星级评分和阅读时长\n      if (type === 'novel' && comment.expand?.score && comment.expand?.score_suffix_text) {\n        const ratingContainer = document.createElement('div')\n        ratingContainer.className = 'mt-2 inline-flex items-center rounded-full bg-amber-50 px-2.5 py-1 text-amber-700 text-xs'\n        // 处理星级评分\n        if (comment.expand?.score) {\n          const score = parseInt(comment.expand.score, 10)\n          const stars = Math.floor(score / 2)\n          const starsContainer = document.createElement('div')\n          starsContainer.className = 'flex mr-2'\n          for (let i = 1; i <= 5; i++) {\n            const star = document.createElement('span')\n            star.textContent = '★'\n            star.className = `mr-0.5 ${i <= stars ? 'text-amber-500' : 'text-stone-300'}`\n            starsContainer.appendChild(star)\n          }\n          ratingContainer.appendChild(starsContainer)\n        }\n        // 处理阅读时长\n        if (comment.expand?.score_suffix_text) {\n          const readTime = document.createElement('span')\n          readTime.textContent = comment.expand.score_suffix_text\n          readTime.className = 'text-amber-700/70'\n          ratingContainer.appendChild(readTime)\n        }\n        commentBody.appendChild(ratingContainer)\n      }\n\n      commentContent.appendChild(commentBody)\n\n      // 回复区（切换+内容）\n      const replyWrapper = document.createElement('div')\n      replyWrapper.className = 'mt-2.5'\n\n      // 评论元信息（时间+IP+点赞/回复）\n      const commentMeta = document.createElement('div')\n      commentMeta.className = 'comment-meta mt-2.5 flex justify-between items-center text-xs'\n      const metaInfo = document.createElement('div')\n      metaInfo.className = 'text-stone-400'\n      metaInfo.textContent = `${formatTimestamp(comment.common?.create_timestamp || comment.create_timestamp || comment.create_time) || '未知'}`\n\n      const actionGroup = document.createElement('div')\n      actionGroup.className = 'flex items-center gap-2'\n\n      // 回复切换按钮（存在回复时显示）\n      const reply_count = comment.stat?.reply_count || comment.reply_count || comment.reply_cnt || comment.reply_outshow_count || comment.reply_show_count || 0\n      let replyToggle = null\n      if (rid && reply_count > 0) { // 无rid不加载回复\n        replyToggle = document.createElement('div')\n        replyToggle.className = 'reply-toggle cursor-pointer'\n        replyToggle.textContent = `展开${reply_count}条回复`\n        // 绑定回复加载事件\n        replyToggle.addEventListener('click', () => {\n          if (isBookComment || isEndComment) openReplyPage(comment, getCommentPlainText(comment), false)\n          else loadReplies(comment, replyWrapper, replyToggle)\n        })\n        if (!(isBookComment || isEndComment)) replyWrapper.appendChild(replyToggle)\n      }\n\n      // 点赞\n      const likeBtn = document.createElement('div')\n      likeBtn.className = 'like-pill flex items-center transition-colors'\n      likeBtn.innerHTML = `${likeSvg} ${comment.stat?.digg_count || comment.digg_count || comment.digg_cnt || 0}`\n      actionGroup.appendChild(likeBtn)\n      if ((isBookComment || isEndComment) && replyToggle) actionGroup.appendChild(replyToggle)\n      commentMeta.appendChild(metaInfo)\n      commentMeta.appendChild(actionGroup)\n      commentContent.appendChild(commentMeta)\n      commentContent.appendChild(replyWrapper)\n      // 回复内容容器（初始隐藏）\n      const repliesContainer = document.createElement('div')\n      repliesContainer.className = 'replies-container mt-2 space-y-1 hidden pl-0'\n      replyWrapper.appendChild(repliesContainer)\n\n      // 回复加载更多按钮（初始隐藏）\n      const replyMore = document.createElement('div')\n      replyMore.className = 'reply-more cursor-pointer mt-2 hidden'\n      replyWrapper.appendChild(replyMore)\n\n      return commentItem\n    }\n\n    function updateCommentTitle(commentListData) {\n      let prompt = ''\n      if (type === 'paragraph') {\n        prompt = isEndComment ? (commentListData?.extra?.para_content?.trim() || '章评') : commentListData?.extra?.para_content?.trim()\n      } else if (type === 'chapter') {\n        prompt = commentListData?.extra?.para_content?.trim() || commentListData?.mix_data?.find(v => v?.comment)?.comment?.item_info?.title?.trim() || '章评'\n      } else if (type === 'novel') {\n        prompt = commentListData?.extra?.book_info?.book_name?.trim()\n        prompt = prompt ? ('《' + prompt + '》') : '书籍评论'\n      }\n      if (prompt) document.getElementById('title').textContent = prompt.length > 50 ? prompt.slice(0, 50) + '...' : prompt\n    }\n\n    function normalizeCommentPage(commentListData, pageNo) {\n      let comments = []\n      let total = 0\n      let end = false\n      if (type === 'paragraph' || type === 'novel') {\n        const { common_list_info, data_list } = commentListData\n        total = common_list_info?.total || 0\n        comments = data_list?.map(item => item.comment) || []\n        if (type === 'novel') {\n          if (common_list_info?.has_more === false) end = true\n          else if (total > 0) end = total <= renderedCommentCount + comments.length\n          else end = !comments.length\n        } else {\n          end = !common_list_info?.has_more\n        }\n      } else if (type === 'chapter') {\n        const { mix_data, item_related_count, has_more } = commentListData\n        total = item_related_count || 0\n        comments = (commentListData.data_list && commentListData.data_list.length)\n          ? commentListData.data_list.map(item => item.comment)\n          : (mix_data?.map(item => item.comment || item.post_data) || [])\n        end = !has_more\n      }\n      return { page: pageNo, raw: commentListData, comments: comments, total: total, end: end }\n    }\n\n    async function fetchCommentPage(pageNo, showLoading) {\n      if (showLoading) loading.classList.remove('hidden')\n      try {\n        const response = await fetchWithToken('./' + type + '_list?bid=' + encodeURIComponent(bid) + '&cid=' + encodeURIComponent(cid) + '&pid=' + encodeURIComponent(pid) + '&page=' + encodeURIComponent(pageNo) + '&size=' + encodeURIComponent(commentSize))\n        const result = await response.json()\n        if (result.code !== 0) throw new Error(result.error || ('获取' + typeZH + '失败'))\n        return normalizeCommentPage(result.data || {}, pageNo)\n      } finally {\n        if (showLoading) loading.classList.add('hidden')\n      }\n    }\n\n    function renderComments(comments) {\n      if (!comments || comments.length === 0) {\n        if (renderedCommentCount === 0) commentList.innerHTML = stateNote('暂无' + typeZH)\n        return\n      }\n      comments.forEach(comment => {\n        const commentDom = renderComment(comment)\n        if (commentDom.children.length) {\n          commentList.appendChild(commentDom)\n          renderedCommentCount++\n        }\n      })\n      commentCountElement.textContent = '共' + commentTotalCount + '条' + typeZH + '  已加载' + renderedCommentCount + '条'\n    }\n\n    function appendCommentEndNote() {\n      if (commentList.querySelector('[data-comment-end]')) return\n      const endDiv = document.createElement('div')\n      endDiv.className = 'state-note'\n      endDiv.setAttribute('data-comment-end', '1')\n      endDiv.textContent = typeZH + '已经到底了~'\n      commentList.appendChild(endDiv)\n    }\n\n    function applyCommentPage(pageData) {\n      if (!pageData) return\n      if (pageData.page === 1) {\n        commentList.classList.remove('hidden')\n        updateCommentTitle(pageData.raw)\n      }\n      commentTotalCount = pageData.total || commentTotalCount || 0\n      renderComments(pageData.comments)\n      isCommentEnd = !!pageData.end\n      if (!isCommentEnd) {\n        commentPage = pageData.page + 1\n        prefetchNextCommentPage()\n      } else {\n        appendCommentEndNote()\n      }\n    }\n\n    async function prefetchNextCommentPage() {\n      const pageNo = commentPage\n      if (isCommentEnd || commentPageCache[pageNo] || commentPrefetching[pageNo]) return\n      commentPrefetching[pageNo] = true\n      try {\n        commentPageCache[pageNo] = await fetchCommentPage(pageNo, false)\n      } catch (e) {\n        console.warn('预加载' + typeZH + '失败:', e)\n      } finally {\n        delete commentPrefetching[pageNo]\n      }\n    }\n\n    // 加载评论列表\n    async function loadComments() {\n      if (isLoading || isCommentEnd) return\n      isLoading = true\n      try {\n        if (commentPageCache[commentPage]) {\n          const cached = commentPageCache[commentPage]\n          delete commentPageCache[commentPage]\n          applyCommentPage(cached)\n          return\n        }\n        const pageData = await fetchCommentPage(commentPage, true)\n        applyCommentPage(pageData)\n      } catch (error) {\n        console.error('加载' + typeZH + '失败:', error)\n        showError(error.message)\n      } finally {\n        isLoading = false\n      }\n    }\n\n\n    function getCommentPlainText(comment) {\n      const common = comment && (comment.Common || comment.common)\n      return String((common && common.content && common.content.text) || comment.text || comment.pure_content || '').trim()\n    }\n\n    function getReplyId(reply) {\n      return String((reply && (reply.comment_id || reply.post_id || reply.reply_id || reply.id)) || '')\n    }\n\n    function getGroupId(item, fallback) {\n      return String((item && (item.reply_group_id || item.group_id || item.parent_id || item.root_id || item.post_id)) || fallback || '')\n    }\n\n    function isPostComment(comment) {\n      return !!(comment && comment.post_id)\n    }\n\n    function waitForPaint() {\n      return new Promise(resolve => {\n        if (typeof requestAnimationFrame === 'function') {\n          requestAnimationFrame(() => requestAnimationFrame(() => setTimeout(resolve, 30)))\n        } else {\n          setTimeout(resolve, 80)\n        }\n      })\n    }\n\n    function stateNote(text, extraClass) {\n      return '<div class=\"' + (extraClass || 'state-note') + '\">' + escapeHtml(text) + '</div>'\n    }\n\n    function loadingCard(text) {\n      return '<div class=\"loading-inline\"><span class=\"loading-spinner\"></span><span class=\"loading-text\">' + escapeHtml(text || '加载中...') + '</span></div>'\n    }\n\n    function setLoadingCard(el, text) {\n      el.className = 'loading-inline reply-loading'\n      el.textContent = ''\n      const spinner = document.createElement('span')\n      spinner.className = 'loading-spinner'\n      const label = document.createElement('span')\n      label.className = 'loading-text'\n      label.textContent = text || '加载中...'\n      el.appendChild(spinner)\n      el.appendChild(label)\n    }\n\n    function saveCurrentDetailState() {\n      if (!detailReplyState || detailView.classList.contains('hidden')) return null\n      return {\n        state: detailReplyState,\n        nodes: Array.from(detailView.childNodes),\n        title: document.getElementById('title').textContent\n      }\n    }\n\n    function restoreDetailState(snapshot) {\n      if (!snapshot) return\n      detailReplyState = snapshot.state\n      detailView.innerHTML = ''\n      ;(snapshot.nodes || []).forEach(node => detailView.appendChild(node))\n      document.getElementById('title').textContent = snapshot.title\n      commentList.classList.add('hidden')\n      commentCountElement.classList.add('hidden')\n      detailView.classList.remove('hidden')\n      backFloat.classList.remove('hidden')\n    }\n\n    function showMainPage() {\n      const previous = detailReplyStack.pop()\n      if (previous) {\n        restoreDetailState(previous)\n        return\n      }\n      detailReplyState = null\n      detailView.classList.add('hidden')\n      detailView.innerHTML = ''\n      commentList.classList.remove('hidden')\n      commentCountElement.classList.remove('hidden')\n      backFloat.classList.add('hidden')\n      if (mainTitleText) document.getElementById('title').textContent = mainTitleText\n    }\n\n    function createDetailMoreButton() {\n      const btn = document.createElement('div')\n      btn.className = 'reply-more cursor-pointer mx-auto mt-3'\n      btn.setAttribute('data-reply-more', '1')\n      btn.textContent = '加载更多回复'\n      btn.addEventListener('click', () => loadDetailReplies(false))\n      return btn\n    }\n\n    async function loadDetailReplies(reset) {\n      const state = detailReplyState\n      if (!state || state.loading || state.end) return\n      state.loading = true\n      if (state.moreEl && state.moreEl.parentNode) {\n        state.moreEl.parentNode.removeChild(state.moreEl)\n      }\n      let detailLoadingEl = null\n      const loadingHtml = loadingCard('加载回复中...')\n      if (reset) {\n        detailView.innerHTML = loadingHtml\n      } else {\n        detailLoadingEl = document.createElement('div')\n        setLoadingCard(detailLoadingEl, '加载回复中...')\n        detailView.appendChild(detailLoadingEl)\n      }\n      try {\n        await waitForPaint()\n        const response = await fetchWithToken('./reply?bid=' + encodeURIComponent(bid) + '&cid=' + encodeURIComponent(cid) + '&pid=' + encodeURIComponent(pid) + '&rid=' + encodeURIComponent(state.rid) + '&kind=' + encodeURIComponent(state.kind) + '&group_id=' + encodeURIComponent(state.groupId) + '&second=' + (state.second ? '1' : '0') + '&page=' + encodeURIComponent(state.page) + '&size=' + encodeURIComponent(state.size))\n        const result = await response.json()\n        if (result.code !== 0) throw new Error(result.error || '获取回复失败')\n        const replies = (result.data && result.data.reply_list) || []\n        const info = (result.data && result.data.comment_list_info) || {}\n        if (reset) {\n          detailView.innerHTML = ''\n          state.moreEl = createDetailMoreButton()\n        } else if (detailLoadingEl && detailLoadingEl.parentNode) {\n          detailLoadingEl.parentNode.removeChild(detailLoadingEl)\n        }\n        let appended = 0\n        replies.forEach(reply => {\n          const id = getReplyId(reply)\n          if (id && state.seen[id]) return\n          if (id) state.seen[id] = true\n          detailView.appendChild(renderReply(reply))\n          appended++\n        })\n        state.end = !info.has_more || appended === 0\n        if (!appended && reset) {\n          detailView.innerHTML = stateNote('暂无更多回复')\n          state.end = true\n          return\n        }\n        if (!state.end) {\n          state.page++\n          state.moreEl.textContent = '加载更多回复'\n          detailView.appendChild(state.moreEl)\n        } else if (appended > 0) {\n          const endEl = document.createElement('div')\n          endEl.className = 'state-note'\n          endEl.textContent = '回复已经到底了~'\n          detailView.appendChild(endEl)\n        }\n      } catch (e) {\n        if (reset) {\n          detailView.innerHTML = stateNote(e.message || e, 'state-error')\n        } else {\n          if (detailLoadingEl && detailLoadingEl.parentNode) detailLoadingEl.parentNode.removeChild(detailLoadingEl)\n          if (state.moreEl) {\n            state.moreEl.textContent = '加载失败，点击重试'\n            detailView.appendChild(state.moreEl)\n          }\n        }\n      } finally {\n        state.loading = false\n      }\n    }\n\n    async function openReplyPage(parent, refererContent, second) {\n      const rid = getReplyId(parent)\n      if (!rid) return\n      if (!mainTitleText) mainTitleText = document.getElementById('title').textContent\n      if (!detailView.classList.contains('hidden') && detailReplyState) {\n        const snapshot = saveCurrentDetailState()\n        if (snapshot) detailReplyStack.push(snapshot)\n      }\n      const detailTitleText = String(refererContent || getCommentPlainText(parent) || '回复详情').trim()\n      document.getElementById('title').textContent = detailTitleText.length > 50 ? detailTitleText.slice(0, 50) + '...' : detailTitleText\n      commentList.classList.add('hidden')\n      commentCountElement.classList.add('hidden')\n      detailView.classList.remove('hidden')\n      backFloat.classList.remove('hidden')\n      detailReplyState = {\n        rid: rid,\n        kind: isPostComment(parent) ? 'post' : 'comment',\n        groupId: getGroupId(parent, rid),\n        second: !!second,\n        page: 1,\n        size: 20,\n        loading: false,\n        end: false,\n        seen: {},\n        moreEl: null\n      }\n      await loadDetailReplies(true)\n    }\n\n    backFloat.addEventListener('click', showMainPage)\n\n    // 渲染单条回复\n    function renderReply(reply) {\n      // 回复项容器\n      const replyItem = document.createElement('div')\n      replyItem.className = 'reply-item flex gap-2 py-2'\n\n      // 回复者头像容器\n      const avatarContainer = document.createElement('div')\n      avatarContainer.className = 'relative w-8 h-8 flex shrink-0 items-center justify-center'\n\n      // 头像占位符\n      const avatarPlaceholder = document.createElement('div')\n      avatarPlaceholder.className = 'image-loading absolute w-8 h-8 rounded-full'\n      avatarContainer.appendChild(avatarPlaceholder)\n\n      // 回复者头像\n      const avatar = document.createElement('img')\n      avatar.className = 'avatar w-8 h-8 rounded-full object-contain cursor-pointer relative z-10 opacity-0 transition-opacity duration-300'\n\n      // 头像加载完成处理\n      avatar.onload = function () {\n        avatarPlaceholder.classList.add('hidden')\n        avatar.classList.remove('opacity-0')\n      }\n\n      // 头像加载失败处理\n      avatar.onerror = function () {\n        avatarPlaceholder.classList.remove('image-loading')\n        avatarPlaceholder.classList.add('bg-gray-100', 'flex', 'items-center', 'justify-center', 'text-gray-400')\n        avatarPlaceholder.innerHTML = '<svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z\"></path></svg>'\n      }\n\n      const { Common } = reply\n      const user_info = Common?.user_info || reply.user_info || {}\n\n      // 处理头像 URL（HEIC 转码）\n      handleImageUrl(user_info.base_info?.user_avatar).then(url => avatar.src = url)\n      avatar.alt = user_info.base_info?.user_name || '用户头像'\n      avatarContainer.appendChild(avatar)\n      replyItem.appendChild(avatarContainer)\n\n      // 回复内容区\n      const replyContent = document.createElement('div')\n      replyContent.className = 'flex-1 min-w-0'\n      replyItem.appendChild(replyContent)\n\n      // 昵称+头衔\n      const replyHeader = document.createElement('div')\n      replyHeader.className = 'flex items-center min-w-0 flex-wrap gap-y-1'\n\n      const nickname = document.createElement('span')\n      nickname.className = 'font-medium text-gray-500 text-xs-sm mr-2'\n      nickname.textContent = user_info.base_info?.user_name || '未知'\n      replyHeader.appendChild(nickname)\n\n      // 头衔渲染\n      const userTitleInfoList = user_info.user_tag?.user_title_info || []\n      replyHeader.appendChild(renderTitles(userTitleInfoList, reply.user_action?.author))\n\n      replyContent.appendChild(replyHeader)\n\n      // 回复内容（处理@和emoji）\n      const replyBody = document.createElement('div')\n      replyBody.className = 'mt-1 text-sm leading-relaxed text-stone-700'\n      const quotedNickname = reply.reply_to_user_info?.base_info?.user_name\n      if (quotedNickname) {\n        // 回复他人：显示“回复 @昵称：内容”\n        const quoteSpan = document.createElement('span')\n        quoteSpan.className = 'text-gray-400'\n        quoteSpan.textContent = `@${quotedNickname}`\n        const contentText = document.createElement('span')\n        contentText.className = 'text-stone-700'\n        contentText.innerHTML = `：${formatEmoji(Common.content?.text || '').replace(/\\n/g, '<br>')}`\n        replyBody.appendChild(document.createTextNode('回复 '))\n        replyBody.appendChild(quoteSpan)\n        replyBody.appendChild(contentText)\n      } else {\n        // 直接回复：仅显示内容\n        replyBody.className = 'mt-1 text-sm leading-relaxed text-stone-700'\n        replyBody.innerHTML = formatEmoji(Common.content?.text || '').replace(/\\n/g, '<br>')\n      }\n\n      // 回复图片\n      const imageDataList = Common.content?.image_data_list?.image_data\n      const replyMedia = renderImageContent(imageDataList)\n      if (replyMedia.children.length > 0) {\n        replyBody.appendChild(replyMedia)\n      }\n      replyContent.appendChild(replyBody)\n\n      // 回复元信息（时间+IP+点赞）\n      const replyMeta = document.createElement('div')\n      replyMeta.className = 'reply-meta mt-1.5 flex justify-between items-center text-xs'\n\n      const metaInfo = document.createElement('div')\n      metaInfo.textContent = `${formatTimestamp(Common.create_timestamp) || '未知'}`\n\n      const likeBtn = document.createElement('div')\n      likeBtn.className = 'flex items-center'\n      likeBtn.innerHTML = `${likeSvg} ${reply.stat?.digg_count || 0}`\n      const replyDetailCount = reply.stat?.reply_count || reply.reply_count || reply.reply_cnt || reply.reply_outshow_count || reply.reply_show_count || 0\n      const replyDetailBtn = document.createElement('span')\n      replyDetailBtn.className = 'reply-more text-blue-500 cursor-pointer ml-3'\n      replyDetailBtn.textContent = '查看' + replyDetailCount + '条回复'\n      replyDetailBtn.addEventListener('click', function () {\n        openReplyPage(reply, getCommentPlainText(reply), true)\n      })\n      if ((isBookComment || isEndComment) && !reply.__second_level && replyDetailCount > 0) likeBtn.appendChild(replyDetailBtn)\n\n      replyMeta.appendChild(metaInfo)\n      replyMeta.appendChild(likeBtn)\n      replyContent.appendChild(replyMeta)\n\n      return replyItem\n    }\n\n    // 加载回复（调用/reply接口）\n    async function loadReplies(comment, replyWrapper, toggleEl) {\n      const rid = comment.comment_id\n      if (!rid) return toggleEl.classList.add('hidden')\n      // 获取回复相关DOM\n      const repliesContainer = replyWrapper.querySelector('.replies-container')\n      const replyMore = replyWrapper.querySelector('.reply-more')\n\n      // 初始化回复分页参数\n      let replyPage = 1\n      const replySize = 5\n      let isReplyEnd = false\n\n      // 首次加载：显示回复加载状态，隐藏切换按钮\n      toggleEl.classList.add('hidden')\n      const loadingEl = document.createElement('div')\n      setLoadingCard(loadingEl, '加载回复中...')\n      replyWrapper.appendChild(loadingEl)\n\n      try {\n        const response = await fetchWithToken(`./reply?bid=${bid}&cid=${cid}&pid=${pid}&rid=${rid}&page=${replyPage}&size=${replySize}`)\n        const result = await response.json()\n\n        if (result.code !== 0) {\n          throw new Error(result.error || '获取回复失败')\n        }\n\n        const replyData = result.data\n        const replies = replyData.reply_list || []\n        const comment_list_info = replyData.comment_list_info\n\n        isReplyEnd = !comment_list_info.has_more\n        const left = Math.max(0, comment_list_info.total - +comment_list_info.offset)\n        // 移除加载提示\n        replyWrapper.removeChild(loadingEl)\n\n        // 显示回复容器\n        repliesContainer.classList.remove('hidden')\n        repliesContainer.innerHTML = ''\n\n        // 渲染回复\n        replies.forEach(reply => {\n          const replyDom = renderReply(reply)\n          repliesContainer.appendChild(replyDom)\n        })\n\n        // 处理回复加载更多\n        if (isReplyEnd) {\n          replyMore.classList.add('hidden')\n        } else {\n          replyMore.textContent = `展开剩余${left ? left + '条' : ''}回复`\n          replyMore.classList.remove('hidden')\n\n          // 绑定加载更多回复事件\n          replyMore.addEventListener('click', async () => {\n            if (isReplyEnd) return\n            replyMore.classList.add('hidden')\n            // 添加加载中提示\n            const moreLoadingEl = document.createElement('div')\n            setLoadingCard(moreLoadingEl, '加载回复中...')\n            replyWrapper.appendChild(moreLoadingEl)\n\n            try {\n              replyPage++\n              const moreResponse = await fetchWithToken(`./reply?bid=${bid}&cid=${cid}&pid=${pid}&rid=${rid}&page=${replyPage}&size=${replySize}`)\n              const moreResult = await moreResponse.json()\n\n              if (moreResult.code !== 0) {\n                throw new Error(moreResult.error || '加载更多回复失败')\n              }\n\n              // 移除加载提示\n              replyWrapper.removeChild(moreLoadingEl)\n\n              const moreReplyData = moreResult.data\n              const moreReplies = moreReplyData.reply_list || []\n              const more_comment_list_info = moreReplyData.comment_list_info\n              const left = Math.max(0, more_comment_list_info.total - +more_comment_list_info.offset)\n              isReplyEnd = !more_comment_list_info.has_more\n\n              // 追加渲染回复\n              moreReplies.forEach(reply => {\n                const replyDom = renderReply(reply)\n                repliesContainer.appendChild(replyDom)\n              })\n\n              // 更新加载更多按钮\n              if (isReplyEnd) {\n                replyMore.classList.add('hidden')\n              } else {\n                replyMore.textContent = `展开剩余${left ? left + '条' : ''}回复`\n                replyMore.classList.remove('hidden')\n              }\n            } catch (error) {\n              console.error('加载更多回复失败:', error)\n              showError(error.message)\n              replyWrapper.removeChild(moreLoadingEl)\n            }\n          })\n        }\n      } catch (error) {\n        console.error('加载回复失败:', comment, error)\n        showError(error.message)\n        replyWrapper.removeChild(loadingEl)\n        toggleEl.classList.remove('hidden') // 加载失败恢复切换按钮\n      }\n    }\n\n    // 下拉加载更多评论\n    function initInfiniteScroll() {\n      window.addEventListener('scroll', () => {\n        const doc = document.scrollingElement || document.documentElement\n        const preloadDistance = Math.max(480, Math.floor(window.innerHeight * 0.6))\n        const distanceToBottom = doc.scrollHeight - (window.innerHeight + doc.scrollTop)\n        const shouldPreload = distanceToBottom <= preloadDistance\n        if (detailReplyState && !detailView.classList.contains('hidden')) {\n          if (shouldPreload && !detailReplyState.loading && !detailReplyState.end) loadDetailReplies(false)\n          return\n        }\n        if (shouldPreload && !isLoading && !isCommentEnd) {\n          loadComments()\n        }\n      }, { passive: true })\n    }\n\n    // 初始化页面\n    function init() {\n      // 检查必要参数\n      if (!bid) {\n        showError('参数错误：缺少必要的书籍ID(bid)')\n        return\n      }\n      // 初始化图片全屏功能\n      initFullscreenImage()\n      // 初始化下拉加载\n      initInfiniteScroll()\n      // 首次加载评论\n      loadComments()\n    }\n\n    // 页面加载完成后初始化\n    window.addEventListener('DOMContentLoaded', init);\n  </script>\n</body>\n\n</html>";
